package seokhoon.trade.adapter.web;
import org.junit.jupiter.api.Test; import seokhoon.trade.application.port.in.NewsUseCase; import seokhoon.trade.domain.research.*; import java.time.Instant; import java.util.List;
import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import static org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup;
class NewsControllerTest {@Test void importsAndReturnsSafeArticleView()throws Exception{NewsUseCase use=mock(NewsUseCase.class);when(use.importStock("005930")).thenReturn(new NewsUseCase.ImportResult("삼성전자",1,1,0,NewsImportStatus.SUCCESS,null));Instant from=Instant.parse("2026-06-21T00:00:00Z"),to=Instant.parse("2026-06-22T00:00:00Z");when(use.find("005930",from,to)).thenReturn(List.of(new NewsArticle(1L,"NAVER","제목","요약","https://origin","https://naver","언론사",from,to,"삼성전자","titlehash","sourcehash",NewsCategory.EARNINGS,NewsSentiment.POSITIVE,NewsImportance.HIGH,"reason",to,to)));var mvc=standaloneSetup(new NewsController(use)).build();mvc.perform(post("/api/research/news/import-stock").param("stockCode","005930")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SUCCESS"));mvc.perform(get("/api/research/news").param("stockCode","005930").param("from",from.toString()).param("to",to.toString())).andExpect(status().isOk()).andExpect(jsonPath("$[0].title").value("제목")).andExpect(jsonPath("$[0].link").value("https://naver")).andExpect(jsonPath("$[0].originLink").doesNotExist()).andExpect(jsonPath("$[0].sourceHash").doesNotExist()).andExpect(jsonPath("$[0].query").doesNotExist());}}
